// Changes: App-wide toast notifications using the React Bits SwipeToast (one toast at a time, newest wins).

import { createContext, useCallback, useContext, useState, type ReactNode } from 'react'
import SwipeToast from './reactbits/SwipeToast'

type Tone = 'ok' | 'bad' | 'info'

export interface ToastOptions {
  title: string
  description?: string
  tone?: Tone
  duration?: number
  actionLabel?: string
  onAction?: () => void
}

const FUSE: Record<Tone, string> = { ok: '#34d399', bad: '#fb7185', info: '#818cf8' }

const ToastContext = createContext<(toast: ToastOptions) => void>(() => {})

export const useToast = () => useContext(ToastContext)

export function ToastProvider({ children }: { children: ReactNode }) {
  const [current, setCurrent] = useState<(ToastOptions & { id: number }) | null>(null)
  const show = useCallback((toast: ToastOptions) => setCurrent({ ...toast, id: Date.now() + Math.random() }), [])

  return (
    <ToastContext.Provider value={show}>
      {children}
      {current && (
        <SwipeToast
          key={current.id}
          title={current.title}
          description={current.description}
          actionLabel={current.actionLabel}
          onAction={current.onAction}
          duration={current.duration ?? (current.tone === 'bad' ? 8000 : 3500)}
          fuseColor={FUSE[current.tone ?? 'info']}
          background="#18181b"
          closeButton
          // onClose fires when the exit animation starts; unmount once it has played.
          onClose={() => setTimeout(() => setCurrent((c) => (c?.id === current.id ? null : c)), 700)}
        />
      )}
    </ToastContext.Provider>
  )
}
